import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';
const RESOLVED = Symbol('resolved');

const createSession = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'hello', timestamp: SENT_AT}],
});

const rejectingProvider = (rejection: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
    throw rejection;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

it('calls onError for every non-Error rejection and preserves the caller rejection', async () => {
  const rejections = ['provider said no', {code: 'PROVIDER_REJECTED'}, undefined];
  const observed = [] as Array<{rejection: unknown; error?: Error; callerValue: unknown}>;

  for (const rejection of rejections) {
    let error: Error | undefined;
    const orchestrator = createChatOrchestrator(
      rejectingProvider(rejection),
      new PromptBuilder({identity: 'You are a test assistant.'}),
      undefined,
      {hooks: {onError: async (_session, receivedError) => void (error = receivedError)}}
    );

    const callerValue = await orchestrator.processMessage(createSession()).then(
      () => RESOLVED,
      value => value
    );
    observed.push({rejection, error, callerValue});
  }

  expect(observed).toHaveLength(rejections.length);
  for (const {rejection, error, callerValue} of observed) {
    expect(error).toBeInstanceOf(Error);
    expect(error?.cause).toBe(rejection);
    expect(callerValue).toBe(rejection);
  }
});
## Engine startup

- The engine's `start()` method rejects the returned promise when it cannot bind the configured port, rather than emitting an unhandled error event that would take the process down ([validated by: rejects instead of taking the process down with an unhandled error event](../../src/config.test.ts#L195)).

## Measured semantics — out of scope

Every rejection reaches `onError`; a rejection that is not an `Error` — a thrown string or object — reaches it wrapped in an `Error` whose `cause` is the original value, while the original rejection still propagates to the caller ([validated by: calls onError for every non-Error rejection and preserves the caller rejection](../../src/orchestration/nonErrorRejection.acceptance.test.ts#L24)).
# Definition of Done

> The orchestrator's `catch` gates `onError` on `error instanceof Error`.

**Strategy: `direct`** — `createChatOrchestrator(...).processMessage()` is the real caller seam, and an AI provider can reject with arbitrary values through its `sendMessage` stream.

## Done when these pass

- [ ] **calls onError for every non-Error rejection and preserves the caller rejection** — string, plain-object, and `undefined` provider rejections invoke `onError` once with an `Error` whose `cause` is the original value, while the caller receives the original value unchanged.
      `src/orchestration/nonErrorRejection.acceptance.test.ts`

## Facets

- [ ] Replace the `instanceof Error` gate so every rejection reaches `onError`, wrapping non-`Error` values with their original value as `cause`.
- [ ] Keep the original rejection unchanged at the caller boundary and preserve the existing same-instance behavior for `Error` rejections.
- [ ] Update the config-hooks spec and CHANGELOG to describe the new guarantee for existing consumers.

## Out of scope

- `beforeSession` escaping the `try` block.
- Usage accounting across tool rounds (HALEngine#93).
